// Una salida por CORRIDA de las últimas 48 h.
// 48 y no 24: si el proceso falla un día, al siguiente recupera. La cuenta
// guarda 31 días, así que nunca se pierde nada.
const cuerpo = $input.first().json;
const corridas = (cuerpo && cuerpo.data && cuerpo.data.items) || [];
const desde = Date.now() - 48 * 3600 * 1000;
const out = [];
for (const c of corridas) {
  if (!c.startedAt || new Date(c.startedAt).getTime() < desde) continue;
  out.push({ json: {
    run_id: c.id, actor: c.actId, estado: c.status,
    usd: c.usageTotalUsd || 0,
    dia: String(c.startedAt).slice(0, 10),
    momento: c.startedAt,
    segundos: c.finishedAt ? Math.round((new Date(c.finishedAt) - new Date(c.startedAt)) / 1000) : null,
    dataset_id: c.defaultDatasetId || null,
  } });
}
return out;

// Se emparejan por POSICIÓN las corridas con el conteo de su dataset:
// el paso anterior corre una vez por corrida y conserva el orden.
const corridas = $('Una fila por corrida').all().map((i) => i.json);
const conteos = $input.all().map((i) => i.json);
const porDia = {};
for (let k = 0; k < corridas.length; k++) {
  const c = corridas[k];
  const r = conteos[k] || {};
  const filas = (r.data && typeof r.data.itemCount === "number") ? r.data.itemCount : null;
  const d = c.dia;
  porDia[d] = porDia[d] || { dia: d, corridas: 0, exacto_usd: 0, cobro_sin_datos: 0, sin_conteo: 0, detalle: [] };
  porDia[d].corridas += 1;
  porDia[d].exacto_usd += c.usd;
  // sólo se marca cuando SE SABE que trajo cero · si no se pudo contar, se dice
  if (filas === null) porDia[d].sin_conteo += 1;
  else if (c.usd > 0 && filas === 0) porDia[d].cobro_sin_datos += 1;
  if (porDia[d].detalle.length < 40) porDia[d].detalle.push({ run_id: c.run_id, actor: c.actor, usd: Number(c.usd.toFixed(6)), filas: filas, estado: c.estado, segundos: c.segundos });
}
// 🔴 UN DÍA SÓLO SE REESCRIBE SI LA VENTANA LO CUBRE ENTERO (2026-09-11 · firma b)
//
// El defecto, medido sobre las corridas reales del proveedor:
//   día 06-sep · gasto real US$ 0,158994
//     pase del 06-sep 23:59 → escribía 0,158994   ✅
//     pase del 08-sep 05:00 → escribía 0,034713   🔴 y PISABA al anterior
//   porque la ventana de 48 h se mueve con «ahora»: las corridas tempranas del día
//   se caen fuera y gana la reescritura que MENOS ve. Así quedó la libreta con
//   0,13 donde el proveedor dice 0,158994.
//
// ⇒ La regla: se borra y reescribe SÓLO el día que entra completo en la ventana
//   (ventana_desde <= 00:00 del día). El día que entra a medias NO SE TOCA: la fila
//   que ya está fue escrita por un pase que veía más.
// ⇒ Y lo que no se reconcilió queda ESCRITO en las filas que sí se escriben, para
//   que un día a medias nunca se lea como un día en cero.
const VENTANA_MS = 48 * 3600 * 1000;
const ahora = Date.now();
const ventanaDesde = ahora - VENTANA_MS;

const completos = [];
const parciales = [];
for (const d of Object.values(porDia)) {
  const inicioDia = new Date(d.dia + 'T00:00:00.000Z').getTime();
  const entero = ventanaDesde <= inicioDia;
  (entero ? completos : parciales).push({
    dia: d.dia,
    cubierto_desde: new Date(Math.max(ventanaDesde, inicioDia)).toISOString(),
    visto_usd: Number(d.exacto_usd.toFixed(6)),
    d: d,
  });
}

// 🔴 lo que NO se reconcilió, declarado · nunca un día a medias leído como cero
const sin_reconciliar = parciales.map((p) => ({
  dia: p.dia,
  motivo: 'la ventana de 48 h sólo alcanza este día desde ' + p.cubierto_desde +
    ' · NO se reescribe su fila para no pisarla con un número más incompleto',
  visto_en_este_pase_usd: p.visto_usd,
}));

if (completos.length === 0) {
  // no hay nada seguro que escribir · se dice, no se escribe un cero
  return [];
}

return completos.map(({ d }) => ({ json: {
  fechas: d.dia,
  category: 'api_call',
  service: 'apify',
  amount_usd: Number(d.exacto_usd.toFixed(2)),
  amount_usd_exact: Number(d.exacto_usd.toFixed(6)),
  date: d.dia,
  description: JSON.stringify({
    tipo: 'costo',
    es: 'reconciliacion_del_dia',
    unica_con_plata: true,
    no_sumar_con: "las filas de llamada (service='apify:<funcion>') · ésas van sin importe a propósito",
    cobertura: 'completa',
    ventana_desde: new Date(ventanaDesde).toISOString(),
    ventana_hasta: new Date(ahora).toISOString(),
    // 🔴 los días que este pase NO pudo cerrar, con su motivo
    dias_sin_reconciliar: sin_reconciliar,
    corridas: d.corridas,
    exacto_usd: Number(d.exacto_usd.toFixed(6)),
    aviso_redondeo: (d.exacto_usd > 0 && Number(d.exacto_usd.toFixed(2)) === 0)
      ? 'el gasto real del día fue ' + d.exacto_usd.toFixed(6) + ' · el 0,00 de amount_usd NO significa gratis'
      : null,
    cobro_sin_datos: d.cobro_sin_datos,
    sin_conteo: d.sin_conteo,
    detalle: d.detalle,
  }),
} }));

